import{bQ as a,aL as l,u as o,G as i}from"./chunks/framework.C1gZXFVa.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),t={name:"guide/faq.md"};function s(n,e,h,c,d,r){return l(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><blockquote><p>先按你看到的报错关键词在本页找答案——本页就是按报错场景组织的。找不到，再看文末的「还是没解决？」。</p></blockquote><h2 id="运行-ansible-时提示-command-not-found" tabindex="-1">运行 ansible 时提示 command not found？ <a class="header-anchor" href="#运行-ansible-时提示-command-not-found" aria-label="Permalink to &quot;运行 ansible 时提示 command not found？&quot;">​</a></h2><blockquote><p>普通用户安装时命令被链接到 <code>~/.local/bin</code>，这个目录可能还没加进 PATH。两种解决办法，任选其一：</p></blockquote><ul><li>执行一次 <code>export PATH=&quot;$HOME/.local/bin:$PATH&quot;</code> 再试</li><li>或者重新打开一个终端窗口</li></ul><h2 id="脚本报错「未找到-python3」或「需要-python-3-11」" tabindex="-1">脚本报错「未找到 python3」或「需要 Python &gt;= 3.11」？ <a class="header-anchor" href="#脚本报错「未找到-python3」或「需要-python-3-11」" aria-label="Permalink to &quot;脚本报错「未找到 python3」或「需要 Python &gt;= 3.11」？&quot;">​</a></h2><blockquote><p>按你的系统装一下 Python 即可，不影响其他东西：</p></blockquote><ul><li>EL 9：<code>sudo dnf install -y python3.11 python3.11-venv</code>（没有 venv 子包时装 <code>python3.11-devel</code>）</li><li>Ubuntu 22.04 / Debian 12：<code>sudo apt install -y python3.11 python3.11-venv</code></li><li>Ubuntu 24.04 自带 Python 3.12，一般不会报这个错。</li></ul><h2 id="脚本报错「未找到-wheelhouse」" tabindex="-1">脚本报错「未找到 wheelhouse」？ <a class="header-anchor" href="#脚本报错「未找到-wheelhouse」" aria-label="Permalink to &quot;脚本报错「未找到 wheelhouse」？&quot;">​</a></h2><blockquote><p>⚠️ 几乎都是因为<strong>只拷了 <code>install.sh</code> 一个文件</strong>，或者没有在解压出来的文件夹里运行。</p></blockquote><ul><li>正确做法：把完整的 <code>.tar.gz</code> 解压后，进入 <code>ansible-offline-install-2.0.0-bundle</code> 文件夹再运行。<code>wheelhouse</code> 就是包里存放全部安装文件的文件夹，缺了它就没法离线安装。</li></ul><h2 id="centos-7-能不能用" tabindex="-1">CentOS 7 能不能用？ <a class="header-anchor" href="#centos-7-能不能用" aria-label="Permalink to &quot;CentOS 7 能不能用？&quot;">​</a></h2><blockquote><p>❌ 不能。CentOS 7 已在 2024 年停止维护，自带的 Python 版本也太老，新版 Ansible 装不上。</p></blockquote><ul><li>请把系统换成 EL 9 系列（如 Rocky Linux 9）。本项目最早的版本就是给 CentOS 7 做的，后来整体重构，不再支持。</li></ul><h2 id="会不会把系统原有的-python-搞坏" tabindex="-1">会不会把系统原有的 Python 搞坏？ <a class="header-anchor" href="#会不会把系统原有的-python-搞坏" aria-label="Permalink to &quot;会不会把系统原有的 Python 搞坏？&quot;">​</a></h2><blockquote><p>✅ 不会。Ansible 全部装进独立文件夹，只是把 <code>ansible</code> 等命令做了链接。</p></blockquote><ul><li>具体位置：root 安装在 <code>/opt/ansible-offline</code>，普通用户在 <code>~/ansible-offline</code>。系统 Python 和其他程序完全不受影响。</li></ul><h2 id="包里自带的-collections-我不想装" tabindex="-1">包里自带的 collections 我不想装？ <a class="header-anchor" href="#包里自带的-collections-我不想装" aria-label="Permalink to &quot;包里自带的 collections 我不想装？&quot;">​</a></h2><ul><li>运行 <code>INSTALL_COLLECTIONS=0 bash install.sh</code> 即可跳过。collection 是 Ansible 的插件包，默认附带了两个最常用的，见<a href="/guide/build">自制离线包</a>。</li></ul><h2 id="脚本能显示英文吗" tabindex="-1">脚本能显示英文吗？ <a class="header-anchor" href="#脚本能显示英文吗" aria-label="Permalink to &quot;脚本能显示英文吗？&quot;">​</a></h2><blockquote><p>可以，两种方式：</p></blockquote><ul><li>命令行参数：<code>bash install.sh --lang en</code></li><li>环境变量：<code>ANSIBLE_OFFLINE_LANG=en</code></li></ul><blockquote><p>安装脚本和打包脚本都支持，默认中文。</p></blockquote><h2 id="怎么卸载" tabindex="-1">怎么卸载？ <a class="header-anchor" href="#怎么卸载" aria-label="Permalink to &quot;怎么卸载？&quot;">​</a></h2><ul><li>删掉安装目录和命令链接即可，没有残留：</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># root 安装的：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ansible-offline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/ansible</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 普通用户安装的：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ansible-offline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/ansible</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span></code></pre></div><h2 id="我在联网机器上打包时-连不上-pypi-或-galaxy-怎么办" tabindex="-1">我在联网机器上打包时，连不上 PyPI 或 Galaxy 怎么办？ <a class="header-anchor" href="#我在联网机器上打包时-连不上-pypi-或-galaxy-怎么办" aria-label="Permalink to &quot;我在联网机器上打包时，连不上 PyPI 或 Galaxy 怎么办？&quot;">​</a></h2><blockquote><p>这正是本项目在国内平台设镜像的原因，分两种情况：</p></blockquote><ul><li><strong>只想装 Ansible</strong>：别自己打包了，直接去 GitHub 或 Gitee 的 Releases <a href="/guide/download">下载现成离线包</a>（国内网络选 Gitee），现成包里已经包含 collections。</li><li><strong>确实要自己打包</strong>（比如要换版本）：给 pip 换一个国内源，在打包命令前面加一个环境变量即可：<code>PIP_INDEX_URL=https://pypi.tuna.tsinghua.edu.cn/simple bash scripts/make-offline-bundle.sh</code>（示例是清华源，阿里云等其他国内源也可以）。</li></ul><blockquote><p>⚠️ 但要提醒：collections 是从海外的 Galaxy 下载的，国内没有稳定镜像，这一步连不通时，请用上面下载现成包的办法。</p></blockquote><h2 id="还是没解决" tabindex="-1">还是没解决？ <a class="header-anchor" href="#还是没解决" aria-label="Permalink to &quot;还是没解决？&quot;">​</a></h2><blockquote><p>到主仓库 <a href="https://github.com/ghl1024/ansible-offline-install/issues" target="_blank" rel="noreferrer">Issues</a> 里留言，留言时尽量带上这三样，能省去很多来回：</p></blockquote><ul><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>你的系统版本（<code>cat /etc/os-release</code> 的输出）</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>你用的离线包文件名</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>报错截图或完整报错文字</li></ul>`,33)])])}const b=a(t,[["render",s]]);export{p as __pageData,b as default};
